def split_words(txt: str):
    # If there is any whitespace, split on all whitespace
    if any(ch.isspace() for ch in txt):
        return txt.split()

    # If there is a comma, split on commas
    if ',' in txt:
        return txt.split(',')

    # Otherwise, count lowercase letters whose distance from 'a' is odd
    # That corresponds to letters: b, d, f, h, … i.e., (ord(ch) - ord('a')) is odd
    return sum(1 for ch in txt
               if 'a' <= ch <= 'z' and ((ord(ch) - ord('a')) % 2 == 1))
