def find_word_with_most_unique_chars(words):
    """
    Finds the word with the most unique characters.
    If tied, picks the lexicographically smallest one.
    """
    if not words:
        return None

    def unique_char_count(word):
        return len(set(word))

    return min(
        words,
        key=lambda w: (-unique_char_count(w), w)
    )

