def process_numbers(numbers):
    """
    Sorts an array of integers in descending order and converts integers 
    between 1 and 9 inclusive into their corresponding English words.
    """
    # Helper function to convert integer to English word
    def int_to_word(n):
        words = {
            1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five",
            6: "Six", 7: "Seven", 8: "Eight", 9: "Nine"
        }
        return words.get(n)

    # Sort in descending order and convert valid numbers to words
    return [
        int_to_word(num) 
        for num in sorted(numbers, reverse=True) 
        if 1 <= num <= 9
    ]
