from collections import Counter
import sys

def get_most_frequent_words(input_string: str) -> dict:
    """
    Returns a dictionary of words that appear most frequently 
    in a space-separated input string.
    """
    if not input_string:
        return {}

    words = input_string.split()

    if not words:
        return {}

    word_counts = Counter(words)
    max_frequency = max(word_counts.values())

    return {word: max_frequency for word, count in word_counts.items() 
            if count == max_frequency}

if __name__ == "__main__":
    input_data = sys.stdin.read().strip()
    result = get_most_frequent_words(input_data)
    print(result)
